<?php
require_once __DIR__ . '/../app/layout.php';
$u=current_user(); $pdo=db();
$areas=[
 'Mirpur'=>[23.8067,90.3686], 'Uttara'=>[23.8759,90.3795], 'Dhanmondi'=>[23.7461,90.3742],
 'Mohammadpur'=>[23.7663,90.3586], 'Gulshan'=>[23.7925,90.4078], 'Farmgate'=>[23.7578,90.3890],
 'Dhaka'=>[23.7806,90.3854], 'Motijheel'=>[23.7330,90.4172], 'Old Dhaka'=>[23.7104,90.4074]
];
$sql="SELECT sf.id,sf.food_name,sf.category,sf.quantity_kg,sf.safety_deadline,sf.priority_score,sf.pickup_address,u.name AS donor FROM surplus_food sf JOIN users u ON u.id=sf.restaurant_id WHERE sf.status='available' AND sf.safety_deadline>NOW() AND EXISTS (SELECT 1 FROM food_safety_checks fsc WHERE fsc.surplus_food_id=sf.id AND fsc.result='safe') ORDER BY sf.safety_deadline ASC LIMIT 300";
$foods=$pdo->query($sql)->fetchAll(); $points=[];
$demandRows=$pdo->query("SELECT COALESCE(upazila,area) AS area,COALESCE(district,'') AS district,SUM(required_meals) AS meals,SUM(GREATEST(required_meals-fulfilled_meals,0)) AS unmet,SUM(people_count) AS people,MAX(urgency='critical') AS critical,COUNT(*) AS reports,MAX(updated_at) AS updated_at FROM demand_requests WHERE status IN ('validated','partially_fulfilled') AND needed_by>NOW() GROUP BY COALESCE(upazila,area),COALESCE(district,'') ORDER BY unmet DESC LIMIT 200")->fetchAll(); $demandPoints=[];
foreach($demandRows as $d){$area='Dhaka';foreach($areas as $name=>$coords){if(stripos($d['area'],$name)!==false || stripos($d['district'],$name)!==false){$area=$name;break;}}$demandPoints[]=['area'=>$d['area'],'district'=>$d['district'],'meals'=>(int)$d['meals'],'unmet'=>(int)$d['unmet'],'people'=>(int)$d['people'],'critical'=>(bool)$d['critical'],'reports'=>(int)$d['reports'],'lat'=>$areas[$area][0],'lng'=>$areas[$area][1]];}
foreach($foods as $f){$area='Dhaka';foreach($areas as $name=>$coords){if(stripos($f['pickup_address'],$name)!==false){$area=$name;break;}}$points[]=['id'=>(int)$f['id'],'name'=>$f['food_name'],'category'=>$f['category'],'qty'=>(float)$f['quantity_kg'],'deadline'=>date('d M, g:i A',strtotime($f['safety_deadline'])),'priority'=>(int)$f['priority_score'],'address'=>$f['pickup_address'],'donor'=>$f['donor'],'area'=>$area,'lat'=>$areas[$area][0],'lng'=>$areas[$area][1]];}
page_header('Area-wise food rescue map'); ?>
<div class="page-intro"><div class="eyebrow">BANGLADESH · AREA OVERVIEW</div><h1>Area-wise food <em>map.</em></h1><p>Safety-approved active listings shown by approximate area centre. This map does not geocode exact street addresses or calculate road distance.</p></div>
<div class="alert warning">Location privacy: map markers use area-level approximate coordinates inferred from pickup address text, not the donor's exact GPS location.</div>
<div class="form-panel"><div style="display:flex;gap:12px;flex-wrap:wrap;align-items:center;justify-content:space-between"><div><strong><?= count($points) ?> safe, active listings</strong> · <strong><?= count($demandPoints) ?> verified demand areas</strong><p class="muted" style="margin:5px 0 0">Green markers = available safe food · Red/orange circles = verified unmet demand</p></div><label>Filter area <select id="map-area"><option value="all">All areas</option><?php foreach(array_keys($areas) as $a): ?><option><?= e($a) ?></option><?php endforeach; ?></select></label></div><div id="food-map" style="height:500px;border-radius:14px;margin-top:16px"></div><p class="muted">Map tiles need internet access. For exact live location, the restaurant must provide coordinates and the user must consent.</p>
<?php if (count($points)===0 && in_array(strtolower((string)($_SERVER['HTTP_HOST'] ?? '')), ['localhost','localhost:80','127.0.0.1','127.0.0.1:80'], true)): ?><div class="alert warning"><strong>No food markers yet.</strong> Run <code>php scripts/seed_demo.php</code> from the project root in XAMPP Shell, then reload this map. Markers use approximate area centres.</div><?php endif; ?></div>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script>
const foodPoints=<?= json_encode($points,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>;
const demandPoints=<?= json_encode($demandPoints,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP) ?>;
if(window.L){const map=L.map('food-map').setView([23.7806,90.3854],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const layer=L.layerGroup().addTo(map);function draw(){layer.clearLayers();const a=document.getElementById('map-area').value;foodPoints.filter(f=>a==='all'||f.area===a).forEach(f=>L.circleMarker([f.lat,f.lng],{radius:7,color:'#14804a',fillColor:'#20a464',fillOpacity:.9}).addTo(layer).bindPopup(`<strong>Safe food: ${escapeText(f.name)}</strong><br>${escapeText(f.category)} · ${f.qty} kg<br>${escapeText(f.area)}<br>Priority ${f.priority}/100<br>Safe deadline: ${escapeText(f.deadline)}<br>${escapeText(f.address)}`));demandPoints.filter(d=>a==='all'||d.area.toLowerCase().includes(a.toLowerCase())||d.district.toLowerCase().includes(a.toLowerCase())).forEach(d=>L.circleMarker([d.lat,d.lng],{radius:Math.min(18,8+Math.log10(d.unmet+1)*3),color:d.critical?'#b91c1c':'#c56a13',fillColor:d.critical?'#ef4444':'#f59e0b',fillOpacity:.65,weight:2}).addTo(layer).bindPopup(`<strong>Verified food demand</strong><br>${escapeText(d.area)} ${escapeText(d.district)}<br>People reported: ${d.people}<br>Meals requested: ${d.meals}<br><strong>Unmet meals: ${d.unmet}</strong><br>Active reports: ${d.reports}<br>Urgency: ${d.critical?'Critical reported':'Review urgency in dashboard'}<br><small>Approximate area centre only; no beneficiary pinpointing.</small>`));}function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}document.getElementById('map-area').addEventListener('change',draw);draw();}else{document.getElementById('food-map').textContent='Map library could not load. Check internet access.';}
</script>
<?php page_footer(); ?>